import json,random,subprocess,copy
MAIN=['python3','-I','/workspace/submission/main.py']
rng=random.Random(99)
base={"zones":[{"origin":"test.","records":[{"owner":"a.test.","type":"A","data":"192.0.2.1"},{"owner":"*.test.","type":"CNAME","data":"end.test."}]}],
      "profiles":[{"id":"p","max_aliases":2,"cname":"follow","wildcard":"rfc"}],
      "queries":[{"id":"q","name":"a.test.","type":"A","cost":1}],
      "observations":[{"id":"o","query":"q","profile":"p","result":{"status":"response","rcode":"NOERROR","answer":[{"owner":"a.test.","type":"A","data":"192.0.2.1"}]}}]}
weird=[None,True,False,0,1,-1,1.5,float('inf'),"", "x", [], {}, [1], {"x":1}]
def rand_mutate(obj,depth=0):
    r=rng.random()
    if isinstance(obj,list):
        if obj and r<0.5:
            i=rng.randrange(len(obj)); 
            if rng.random()<0.5: obj[i]=rand_mutate(obj[i],depth+1)
            else: del obj[i]
        elif r<0.75: obj.append(copy.deepcopy(rng.choice(weird)))
        else: obj.append(rand_mutate(copy.deepcopy(rng.choice(obj)) if obj else {},depth+1))
    elif isinstance(obj,dict):
        keys=list(obj)
        if keys and r<0.6:
            k=rng.choice(keys)
            if rng.random()<0.3: del obj[k]
            elif rng.random()<0.5: obj[rng.choice(["zz","id","origin","status","type"])]=rng.choice(weird)
            else: obj[k]=rand_mutate(obj[k],depth+1)
        elif r<0.8: obj[rng.choice(["extra","x"])] = rng.choice(weird)
    return obj
bad=0
for i in range(300):
    doc=copy.deepcopy(base)
    for _ in range(rng.randint(1,4)): rand_mutate(doc)
    try: raw=json.dumps(doc).encode()
    except Exception: continue
    p=subprocess.run(MAIN,input=raw,capture_output=True)
    if p.returncode!=0:
        print("nonzero",p.returncode,raw[:200],p.stderr[:200]); bad+=1; break
    try: out=json.loads(p.stdout)
    except Exception:
        print("bad json out",p.stdout[:200]); bad+=1; break
    if 'error' not in out:
        # mutation might still be valid; check root fields
        if set(out)!={'runs','audits','diagnostic'}:
            print("unexpected out",out.keys()); bad+=1; break
print("done bad",bad)
